package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

var _ = decimal.NewFromInt

type DateRec struct {
	DtId   string
	DtYyyy int64
	DtMm   int64
	DtDd   int64
}

var WsEofFlag string = "N"
var WsLeapFlag string = "N"
var WsQ int64 = 0
var WsR4 int64 = 0
var WsR100 int64 = 0
var WsR400 int64 = 0
var WsMaxDay int64 = 0
var WsValid int64 = 0
var WsBadMonth int64 = 0
var WsBadDay int64 = 0

var dateRec DateRec

var dateFile *os.File
var reader *bufio.Scanner
var atEOF bool

func isInputDone() bool { return WsEofFlag == "Y" }
func isLeap() bool      { return WsLeapFlag == "Y" }

func pow10(n int) int64 {
	var p int64 = 1
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func truncToPic(value int64, digits int) int64 {
	mod := pow10(digits)
	v := value % mod
	if v < 0 {
		v += mod
	}
	return v
}

func formatUneditedInt(value int64, digits int) string {
	// COBOL DISPLAY of unedited numeric: zero-padded to digit count, high-order truncated
	v := truncToPic(value, digits)
	return fmt.Sprintf("%0*d", digits, v)
}

func parsePic9(s string) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	// keep only digits and sign? For this program only positive digits
	// If contains non-digit, treat as 0? But just parse
	v, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		// try to extract digits
		neg := false
		var digits strings.Builder
		for _, ch := range s {
			if ch >= '0' && ch <= '9' {
				digits.WriteRune(ch)
			} else if ch == '-' {
				neg = true
			}
		}
		if digits.Len() == 0 {
			return 0
		}
		v, _ = strconv.ParseInt(digits.String(), 10, 64)
		if neg {
			v = -v
		}
	}
	return v
}

func padLine(line string, length int) string {
	if len(line) < length {
		return line + strings.Repeat(" ", length-len(line))
	}
	if len(line) > length {
		return line[:length]
	}
	return line
}

func MAIN_PARA() {
	var err error
	dateFile, err = os.Open("input.dat")
	if err != nil {
		// if file not found, treat as empty
		dateFile = nil
		reader = nil
		atEOF = true
	} else {
		reader = bufio.NewScanner(dateFile)
		// allow long lines
		reader.Buffer(make([]byte, 0, 64*1024), 10*1024*1024)
	}
	READ_PARA()
	for !isInputDone() {
		PROCESS_PARA()
	}
	if dateFile != nil {
		dateFile.Close()
	}
	// DISPLAY "VALID: " WS-VALID " BAD MONTH: " WS-BAD-MONTH " BAD DAY: " WS-BAD-DAY
	fmt.Printf("VALID: %s BAD MONTH: %s BAD DAY: %s\n",
		formatUneditedInt(WsValid, 2),
		formatUneditedInt(WsBadMonth, 2),
		formatUneditedInt(WsBadDay, 2),
	)
}

func READ_PARA() {
	if reader == nil {
		WsEofFlag = "Y"
		return
	}
	if !reader.Scan() {
		WsEofFlag = "Y"
		return
	}
	line := reader.Text()
	// LINE SEQUENTIAL strips newline, keep as is (may contain spaces)
	// Need to handle CRLF already stripped
	// Pad to record length
	rec := padLine(line, 12)
	dateRec.DtId = rec[0:4]
	dateRec.DtYyyy = parsePic9(rec[4:8])
	dateRec.DtMm = parsePic9(rec[8:10])
	dateRec.DtDd = parsePic9(rec[10:12])
}

func PROCESS_PARA() {
	LEAP_PARA()
	if dateRec.DtMm < 1 || dateRec.DtMm > 12 {
		WsBadMonth = truncToPic(WsBadMonth+1, 2)
		fmt.Printf("%s BAD MONTH %s\n", dateRec.DtId, formatUneditedInt(dateRec.DtMm, 2))
	} else {
		DAYS_PARA()
		if dateRec.DtDd < 1 || dateRec.DtDd > WsMaxDay {
			WsBadDay = truncToPic(WsBadDay+1, 2)
			fmt.Printf("%s BAD DAY %s MAX %s\n", dateRec.DtId, formatUneditedInt(dateRec.DtDd, 2), formatUneditedInt(WsMaxDay, 2))
		} else {
			WsValid = truncToPic(WsValid+1, 2)
			fmt.Printf("%s VALID %s-%s-%s\n", dateRec.DtId, formatUneditedInt(dateRec.DtYyyy, 4), formatUneditedInt(dateRec.DtMm, 2), formatUneditedInt(dateRec.DtDd, 2))
		}
	}
	READ_PARA()
}

func LEAP_PARA() {
	// DIVIDE DT-YYYY BY 4 GIVING WS-Q REMAINDER WS-R4
	// COBOL DIVIDE: GIVING is quotient truncated toward zero, remainder = dividend - quotient*divisor
	// For positive numbers, standard integer division
	WsQ = truncToPic(dateRec.DtYyyy/4, 4)
	WsR4 = dateRec.DtYyyy % 4
	if WsR4 < 0 {
		WsR4 = -WsR4
	}
	WsR4 = truncToPic(WsR4, 3)

	WsQ = truncToPic(dateRec.DtYyyy/100, 4)
	WsR100 = dateRec.DtYyyy % 100
	if WsR100 < 0 {
		WsR100 = -WsR100
	}
	WsR100 = truncToPic(WsR100, 3)

	WsQ = truncToPic(dateRec.DtYyyy/400, 4)
	WsR400 = dateRec.DtYyyy % 400
	if WsR400 < 0 {
		WsR400 = -WsR400
	}
	WsR400 = truncToPic(WsR400, 3)

	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func DAYS_PARA() {
	switch dateRec.DtMm {
	case 2:
		if isLeap() {
			WsMaxDay = truncToPic(29, 2)
		} else {
			WsMaxDay = truncToPic(28, 2)
		}
	case 4, 6, 9, 11:
		WsMaxDay = truncToPic(30, 2)
	default:
		WsMaxDay = truncToPic(31, 2)
	}
}

func main() {
	MAIN_PARA()
}
